<?php
use App\Core\{DB,Security,Mailer};
use App\Models\{Project,ProjectEmail,Ticket,Team};
use App\Services\Notifications;

$np=Project::save(['name'=>'Notifications A','key'=>'NA'.strtoupper(bin2hex(random_bytes(3)))]);
$npOther=Project::save(['name'=>'Notifications B','key'=>'NB'.strtoupper(bin2hex(random_bytes(3)))]);
$recipient=DB::insert("INSERT INTO users(email,name,password_hash,role,verified_at) VALUES(?,?,?,'member',UTC_TIMESTAMP())",['notify.'.bin2hex(random_bytes(4)).'@example.com','Destinataire test',Security::password('Synthetic-Notifications-2026!')]);
$oldOwner=DB::insert("INSERT INTO users(email,name,password_hash,role,verified_at) VALUES(?,?,?,'member',UTC_TIMESTAMP())",['previous.'.bin2hex(random_bytes(4)).'@example.com','Ancien responsable',Security::password('Synthetic-Notifications-2026!')]);
check(!ProjectEmail::get($np)['enabled'],'notifications désactivées tant que le projet ne les configure pas');
$noNotify=Ticket::create($np,['title'=>'Sans notification','assignee_id'=>$recipient],$uid);
check(!DB::one('SELECT id FROM notification_outbox WHERE ticket_id=?',[$noNotify]),'aucun envoi implicite pour un projet non configuré');
$rules=array_fill_keys(array_keys(ProjectEmail::EVENTS),['reporter','assignee','team','project_teams','selected']);
ProjectEmail::save($np,['version'=>0,'enabled'=>1,'rules'=>$rules,'recipients'=>[$recipient]]);
rejects(fn()=>ProjectEmail::save($np,['version'=>0,'enabled'=>1,'rules'=>[]]),'réglage de notification obsolète refusé');
rejects(fn()=>ProjectEmail::save($np,['version'=>1,'rules'=>['unknown'=>['admins']]]),'événement notification inconnu refusé');
rejects(fn()=>ProjectEmail::save($np,['version'=>1,'rules'=>['created'=>['everyone']]]),'rôle de destinataire inconnu refusé');
$nt=Team::save(null,'Équipe notifications '.bin2hex(random_bytes(3)));
Team::membership($nt,$recipient,true);Team::projectMembership($nt,$np,true);
$notifyTicket=Ticket::create($np,['title'=>'Premier signal','assignee_id'=>$recipient,'team_id'=>$nt],$uid);
$queued=DB::all('SELECT * FROM notification_outbox WHERE ticket_id=?',[$notifyTicket]);
check(count($queued)===1 && (int)$queued[0]['recipient_id']===$recipient,'destinataires dédupliqués entre responsable, équipe et personnes choisies, auteur exclu');
check(!str_contains($queued[0]['body'],'password') && str_contains($queued[0]['body'],url('/tickets/'.$notifyTicket)),'notification minimale avec lien de connexion au ticket');
$beforeCount=(int)DB::one('SELECT COUNT(*) n FROM notification_outbox')['n'];
Ticket::create($npOther,['title'=>'Autre projet','assignee_id'=>$recipient],$uid);
check((int)DB::one('SELECT COUNT(*) n FROM notification_outbox')['n']===$beforeCount,'politique de notifications indépendante par projet');
Ticket::patch($notifyTicket,['status'=>'done','priority'=>'high'],$uid,Ticket::find($notifyTicket)['version']);
Ticket::comment($notifyTicket,'Commentaire confidentiel non recopié',$uid);
$queued=DB::all('SELECT * FROM notification_outbox WHERE ticket_id=?',[$notifyTicket]);
$events=json_decode($queued[0]['events_json'],true);
check(count($queued)===1 && in_array('completed',$events,true) && in_array('commented',$events,true) && in_array('updated',$events,true),'plusieurs événements du même ticket regroupés en un e-mail par requête');
check(!str_contains($queued[0]['body'],'Commentaire confidentiel'),'texte des commentaires non recopié dans les e-mails');
$nullHours=Ticket::create($np,['title'=>'Temps stable','estimated_hours'=>'2.50','assignee_id'=>$recipient],$uid);
Ticket::patch($nullHours,['estimated_hours'=>'2,5'],$uid,Ticket::find($nullHours)['version']);
$events=json_decode(DB::one('SELECT events_json FROM notification_outbox WHERE ticket_id=?',[$nullHours])['events_json'],true);
check($events===['created'],'même estimation décimale ne crée pas une modification fictive');
$reassigned=Ticket::create($np,['title'=>'Réaffectation','assignee_id'=>$oldOwner],$uid);
Ticket::patch($reassigned,['assignee_id'=>$recipient],$uid,Ticket::find($reassigned)['version']);
check((int)DB::one('SELECT COUNT(*) n FROM notification_outbox WHERE ticket_id=?',[$reassigned])['n']===2,'ancien et nouveau responsables informés de la réaffectation');
DB::run('UPDATE users SET ticket_email_enabled=0 WHERE id=?',[$recipient]);
$muted=Ticket::create($np,['title'=>'Préférence personnelle','assignee_id'=>$recipient],$uid);
check(!DB::one('SELECT id FROM notification_outbox WHERE ticket_id=?',[$muted]),'préférence personnelle respectée lors de la mise en attente');
DB::run('UPDATE users SET ticket_email_enabled=1,active=0 WHERE id=?',[$recipient]);
$inactive=Ticket::create($np,['title'=>'Compte désactivé'],$uid);
check(!DB::one('SELECT id FROM notification_outbox WHERE ticket_id=?',[$inactive]),'compte désactivé exclu des destinataires fixes');
DB::run('UPDATE users SET active=1 WHERE id=?',[$recipient]);
Team::delete($nt,$uid);
check(in_array('team_id',json_decode(DB::one('SELECT fields_json FROM notification_outbox WHERE ticket_id=?',[$notifyTicket])['fields_json'],true),true),'retrait d’équipe lors de sa suppression utilise les mêmes notifications métier');
DB::run('SAVEPOINT notification_failure');
$rolled=Ticket::create($np,['title'=>'À annuler','assignee_id'=>$recipient],$uid);
DB::run('ROLLBACK TO SAVEPOINT notification_failure');
check(!DB::one('SELECT id FROM notification_outbox WHERE ticket_id=?',[$rolled]),'annulation transactionnelle supprime aussi les notifications');
$blocked=false;try { Notifications::deliver(); } catch(RuntimeException) { $blocked=true; }
check($blocked,'aucun envoi avant validation de la transaction');
ProjectEmail::save($np,['version'=>1,'enabled'=>0,'rules'=>$rules,'recipients'=>[$recipient]]);
check((int)DB::one("SELECT COUNT(*) n FROM notification_outbox WHERE project_id=? AND state='pending'",[$np])['n']===0,'désactiver le projet annule ses envois en attente');
$previousTransport=getenv('MAIL_TRANSPORT');putenv('MAIL_TRANSPORT=unsupported');$failed=false;
try { Mailer::send('test@example.com','Test','Test'); } catch(RuntimeException) { $failed=true; }
putenv($previousTransport===false?'MAIL_TRANSPORT':'MAIL_TRANSPORT='.$previousTransport);
check($failed,'transport de messagerie inconnu refusé sans tentative d’envoi');
